local function apply()
  for _, shard in ipairs(shards) do RequestStreamedTextureDict(shard, false) end
  local timeout = GetGameTimer() + 30000
  while GetGameTimer() < timeout do
    local ready = true
    for _, shard in ipairs(shards) do if not HasStreamedTextureDictLoaded(shard) then ready = false; break end end
    if ready then break end
    Wait(100)
  end
  for txd, entries in pairs(replacements) do
    for _, e in ipairs(entries) do AddReplaceTexture(txd, e[1], e[2], e[3]) end
  end
end

CreateThread(function() while true do apply(); Wait(30000) end end)
AddEventHandler('playerSpawned', function() Wait(2500); apply() end)
